### Java
```java
import java.util.Arrays;

public class Main {
    public static void main(String[] args) {
        int[] array = new int[11];
        for (int i = 0; i < 11; i++) {
            array[i] = i;
        }
        System.out.println(Arrays.toString(array));
    }
}
```

### C++
```cpp
#include <iostream>
#include <vector>

int main() {
    std::vector<int> array(11);
    for (int i = 0; i < 11; i++) {
        array[i] = i;
    }
    for (int i = 0; i < 11; i++) {
        std::cout << array[i] << " ";
    }
    return 0;
}
